def mkdir(self, p):
    """Make the specified directory and all intermediate parent
    directories.

    :param p: the path of the directory to create
    :type p: str
    """
    if p == '':
        raise ValueError('empty path')
    if self._fs.exists(p):
        raise OSError('Destination exists: %s' % p)
    d = os.path.dirname(p)
    if d and (not self._fs.exists(d)):
        self.mkdir(d)
    self._fs.mkdir(p)

